using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// A cosmetic skin for one kingdom board and its pieces, generated by tools/theme-lab.
/// Every theme shares one layout: the board sprite holds a 4x4 grid of holes on a
/// 208/1024 pitch, so slots, pieces and state overlays line up for any theme.
/// </summary>
[CreateAssetMenu(menuName = "Busara/Board Theme", fileName = "BoardTheme")]
public class BoardTheme : ScriptableObject
{
    /// <summary>Hole pitch as a fraction of the board sprite's width.</summary>
    public const float SlotPitch = 208f / 1024f;

    public string id;
    public string displayName;
    public string era;
    [TextArea] public string origin;

    [Header("Board")]
    public Sprite board;
    public Sprite turnGlow;

    [Header("Pieces")]
    public Sprite water;
    public Sprite earth;
    public Sprite fire;
    public Sprite air;
    public Sprite hidden;
    public Sprite pieceSelected;
    public Sprite pieceThreatened;
    public Sprite pieceShielded;

    [Header("Piece sprite geometry")]
    [Tooltip("Piece sprite height / width. Tall shapes rise above their slot and overlap the row behind.")]
    public float pieceAspect = 1f;
    [Tooltip("Height of the piece's base centre above the sprite's bottom edge, as a fraction of its height.")]
    [Range(0f, 1f)] public float piecePivotY = 0.5f;

    [Header("Piece layers")]
    [Tooltip("Each piece as a stack of shared layer sprites (Sprites/Pieces/<shape>/), drawn bottom to top with " +
             "their tint. When set, pieces are composited from these so seats can recolour them; the single piece " +
             "sprites above are the same art pre-composited and remain the fallback.")]
    public List<PieceLayer> waterLayers = new List<PieceLayer>();
    public List<PieceLayer> earthLayers = new List<PieceLayer>();
    public List<PieceLayer> fireLayers = new List<PieceLayer>();
    public List<PieceLayer> airLayers = new List<PieceLayer>();
    public List<PieceLayer> hiddenLayers = new List<PieceLayer>();

    [Header("Slot overlays")]
    public Sprite slotHover;
    public Sprite slotLegal;
    public Sprite slotBlocked;
    public Sprite slotSelected;
    public Sprite slotTarget;

    [Header("Colours")]
    public Color accent = Color.white;
    public Color danger = Color.red;
    public Color light = Color.white;

    public string DisplayName => string.IsNullOrEmpty(displayName) ? name : displayName;

    /// <summary>The era as players read it, for menus.</summary>
    public string EraLabel
    {
        get
        {
            switch (era)
            {
                case "past": return "Past kingdom";
                case "future": return "Future city";
                case "fusion": return "Past meets future";
                case "classic": return "Original board";
                default: return era ?? "";
            }
        }
    }

    public Sprite PieceFor(ResourceType type)
    {
        switch (type)
        {
            case ResourceType.Water: return water;
            case ResourceType.Earth: return earth;
            case ResourceType.Fire: return fire;
            case ResourceType.Air: return air;
            default: return null;
        }
    }

    public List<PieceLayer> LayersFor(ResourceType type)
    {
        switch (type)
        {
            case ResourceType.Water: return waterLayers;
            case ResourceType.Earth: return earthLayers;
            case ResourceType.Fire: return fireLayers;
            case ResourceType.Air: return airLayers;
            default: return null;
        }
    }
}

/// <summary>One layer of a piece: a greyscale or white mask multiplied by its tint, like a UI Image colour.</summary>
[System.Serializable]
public class PieceLayer
{
    [Tooltip("shadow, trim, paint, motif, detail, relief, glyph or glow.")]
    public string name;
    public Sprite sprite;
    [Tooltip("Untinted layers (shadow, detail, relief) keep their own colours.")]
    public bool tinted;
    public Color tint = Color.white;
}
